"use client";

import { useMemo, useState } from "react";
import { Button, Card, Input, Label, Separator } from "@pixa/ui";

type NavItem = {
  title: string;
  items: { title: string; isActive?: boolean }[];
};

const versions = ["1.0.1", "1.1.0-alpha", "2.0.0-beta1"];
const navMain: NavItem[] = [
  {
    title: "Getting Started",
    items: [
      { title: "Installation" },
      { title: "Project Structure" },
    ],
  },
  {
    title: "Build Your Application",
    items: [
      { title: "Routing" },
      { title: "Data Fetching", isActive: true },
      { title: "Rendering" },
      { title: "Caching" },
      { title: "Styling" },
      { title: "Optimizing" },
      { title: "Configuring" },
      { title: "Testing" },
      { title: "Authentication" },
      { title: "Deploying" },
      { title: "Upgrading" },
      { title: "Examples" },
    ],
  },
  {
    title: "API Reference",
    items: [
      { title: "Components" },
      { title: "File Conventions" },
      { title: "Functions" },
      { title: "next.config.js Options" },
      { title: "CLI" },
      { title: "Edge Runtime" },
    ],
  },
  {
    title: "Architecture",
    items: [
      { title: "Accessibility" },
      { title: "Fast Refresh" },
      { title: "Next.js Compiler" },
      { title: "Supported Browsers" },
      { title: "Turbopack" },
    ],
  },
  {
    title: "Community",
    items: [{ title: "Contribution Guide" }],
  },
];

function Page() {
  const [sidebarOpen, setSidebarOpen] = useState(true);
  const [selectedVersion, setSelectedVersion] = useState(versions[0]);
  const [versionMenuOpen, setVersionMenuOpen] = useState(false);
  const [openSections, setOpenSections] = useState<Record<string, boolean>>(
    () =>
      Object.fromEntries(navMain.map((section) => [section.title, true])) as Record<
        string,
        boolean
      >,
  );

  const contentCards = useMemo(() => Array.from({ length: 24 }), []);

  return (
    <div className="page-shell">
      <aside className={`sidebar ${sidebarOpen ? "sidebar-open" : "sidebar-closed"}`}>
        <div className="sidebar-header">
          <div className="version-switcher">
            <Button
              variant="secondary"
              className="version-button"
              onPress={() => setVersionMenuOpen((value) => !value)}
            >
              <span className="version-icon">
                <GalleryIcon />
              </span>
              <span className="version-copy">
                <span className="version-title">Documentation</span>
                <span className="version-value">v{selectedVersion}</span>
              </span>
              <ChevronsUpDownIcon />
            </Button>
            {versionMenuOpen ? (
              <div className="version-menu" role="menu" aria-label="Documentation versions">
                {versions.map((version) => (
                  <button
                    key={version}
                    type="button"
                    className="version-menu-item"
                    onClick={() => {
                      setSelectedVersion(version);
                      setVersionMenuOpen(false);
                    }}
                  >
                    <span>v{version}</span>
                    {version === selectedVersion ? <CheckIcon /> : null}
                  </button>
                ))}
              </div>
            ) : null}
          </div>

          <form className="search-form">
            <Label htmlFor="search" className="sr-only">
              Search
            </Label>
            <div className="search-field">
              <SearchIcon />
              <Input id="search" placeholder="Search the docs..." className="search-input" />
            </div>
          </form>
        </div>

        <nav className="sidebar-content" aria-label="Documentation sections">
          {navMain.map((section) => {
            const isOpen = openSections[section.title];
            return (
              <section key={section.title} className="sidebar-group">
                <button
                  type="button"
                  className="sidebar-group-label"
                  onClick={() =>
                    setOpenSections((current) => ({
                      ...current,
                      [section.title]: !current[section.title],
                    }))
                  }
                >
                  <span>{section.title}</span>
                  <ChevronRightIcon open={isOpen} />
                </button>
                {isOpen ? (
                  <div className="sidebar-group-content">
                    <ul className="sidebar-menu">
                      {section.items.map((item) => (
                        <li key={item.title}>
                          <a
                            href="#"
                            className={`sidebar-menu-button${item.isActive ? " is-active" : ""}`}
                          >
                            {item.title}
                          </a>
                        </li>
                      ))}
                    </ul>
                  </div>
                ) : null}
              </section>
            );
          })}
        </nav>

        <div className="sidebar-rail" />
      </aside>

      <main className="content">
        <header className="content-header">
          <Button
            variant="ghost"
            className="sidebar-trigger"
            onPress={() => setSidebarOpen((value) => !value)}
          >
            <MenuIcon />
            <span>Toggle Sidebar</span>
          </Button>
          <Separator orientation="vertical" className="header-separator" />
          <nav aria-label="breadcrumb">
            <ol className="breadcrumb">
              <li className="breadcrumb-item breadcrumb-hidden">
                <a href="#">Build Your Application</a>
              </li>
              <li className="breadcrumb-separator breadcrumb-hidden">/</li>
              <li className="breadcrumb-item breadcrumb-current">Data Fetching</li>
            </ol>
          </nav>
        </header>

        <section className="content-grid" aria-label="Dashboard content">
          {contentCards.map((_, index) => (
            <Card key={index} className="placeholder-card" />
          ))}
        </section>
      </main>

      <style jsx>{`
        :global(html, body) {
          margin: 0;
          padding: 0;
          min-height: 100%;
          background: #ffffff;
          color: #09090b;
          font-family:
            ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI",
            sans-serif;
        }

        :global(*) {
          box-sizing: border-box;
        }

        :global(a) {
          color: inherit;
          text-decoration: none;
        }

        :global(button),
        :global(input) {
          font: inherit;
        }

        .page-shell {
          display: flex;
          min-height: 100vh;
          background: #ffffff;
        }

        .sidebar {
          width: 288px;
          flex: 0 0 288px;
          border-right: 1px solid #e4e4e7;
          background: #ffffff;
          display: flex;
          flex-direction: column;
          transition: transform 0.2s ease;
        }

        .sidebar-header {
          display: flex;
          flex-direction: column;
          gap: 12px;
          padding: 16px;
        }

        .version-switcher {
          position: relative;
        }

        .version-button,
        .sidebar-group-label,
        .sidebar-trigger,
        .version-menu-item {
          border: 0;
          background: transparent;
          cursor: pointer;
        }

        .version-button {
          width: 100%;
          display: flex;
          align-items: center;
          gap: 12px;
          padding: 10px 12px;
          border-radius: 12px;
          background: #fff;
          box-shadow: inset 0 0 0 1px #e4e4e7;
          color: #09090b;
        }

        .version-icon {
          width: 32px;
          height: 32px;
          flex: 0 0 32px;
          border-radius: 10px;
          background: #18181b;
          color: #fafafa;
          display: grid;
          place-items: center;
        }

        .version-copy {
          display: flex;
          flex-direction: column;
          align-items: flex-start;
          gap: 2px;
          line-height: 1;
        }

        .version-title {
          font-size: 14px;
          font-weight: 500;
        }

        .version-value {
          font-size: 14px;
          color: #71717a;
        }

        .version-menu {
          position: absolute;
          z-index: 10;
          top: calc(100% + 8px);
          left: 0;
          right: 0;
          border: 1px solid #e4e4e7;
          border-radius: 12px;
          background: #ffffff;
          box-shadow: 0 12px 24px rgba(0, 0, 0, 0.08);
          overflow: hidden;
        }

        .version-menu-item {
          width: 100%;
          display: flex;
          align-items: center;
          justify-content: space-between;
          padding: 10px 12px;
          color: #18181b;
          text-align: left;
        }

        .version-menu-item:hover,
        .sidebar-group-label:hover,
        .sidebar-menu-button:hover,
        .sidebar-trigger:hover {
          background: #f4f4f5;
        }

        .search-field {
          position: relative;
        }

        .search-field input {
          width: 100%;
        }

        .search-input {
          padding: 0 12px 0 34px;
        }

        .search-field svg {
          position: absolute;
          left: 10px;
          top: 50%;
          transform: translateY(-50%);
        }

        .sidebar-content {
          display: flex;
          flex-direction: column;
          gap: 0;
          padding-bottom: 12px;
          overflow: auto;
        }

        .sidebar-group {
          display: flex;
          flex-direction: column;
        }

        .sidebar-group-label {
          display: flex;
          align-items: center;
          gap: 8px;
          width: 100%;
          padding: 10px 16px;
          color: #09090b;
          font-size: 14px;
          font-weight: 500;
          text-align: left;
        }

        .sidebar-group-content {
          padding: 0 8px 8px;
        }

        .sidebar-menu {
          list-style: none;
          margin: 0;
          padding: 0;
        }

        .sidebar-menu li + li {
          margin-top: 2px;
        }

        .sidebar-menu-button {
          display: block;
          padding: 8px 12px 8px 20px;
          border-radius: 10px;
          color: #52525b;
          font-size: 14px;
        }

        .sidebar-menu-button.is-active {
          color: #09090b;
          background: #f4f4f5;
          font-weight: 500;
        }

        .sidebar-rail {
          margin-top: auto;
          height: 100%;
          width: 12px;
          align-self: flex-end;
        }

        .content {
          flex: 1;
          min-width: 0;
          display: flex;
          flex-direction: column;
        }

        .content-header {
          position: sticky;
          top: 0;
          z-index: 5;
          display: flex;
          align-items: center;
          gap: 8px;
          height: 64px;
          padding: 0 16px;
          border-bottom: 1px solid #e4e4e7;
          background: #ffffff;
        }

        .sidebar-trigger {
          display: inline-flex;
          align-items: center;
          gap: 8px;
          padding: 8px 12px;
          border-radius: 10px;
          color: #09090b;
        }

        .header-separator {
          width: 1px;
          height: 16px;
          background: #d4d4d8;
        }

        .breadcrumb {
          list-style: none;
          margin: 0;
          padding: 0;
          display: flex;
          align-items: center;
          gap: 8px;
          color: #71717a;
          font-size: 14px;
        }

        .breadcrumb-item a {
          color: #09090b;
        }

        .breadcrumb-current {
          color: #09090b;
        }

        .content-grid {
          flex: 1;
          display: grid;
          grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));
          gap: 16px;
          padding: 16px;
        }

        .placeholder-card {
          height: 48px;
          border-radius: 12px;
          background: rgba(244, 244, 245, 0.9);
          aspect-ratio: 16 / 9;
        }

        .sr-only {
          position: absolute;
          width: 1px;
          height: 1px;
          padding: 0;
          margin: -1px;
          overflow: hidden;
          clip: rect(0, 0, 0, 0);
          white-space: nowrap;
          border: 0;
        }

        @media (max-width: 900px) {
          .page-shell {
            position: relative;
          }

          .sidebar {
            position: absolute;
            inset: 0 auto 0 0;
            height: 100vh;
            box-shadow: 16px 0 48px rgba(0, 0, 0, 0.12);
            transform: translateX(${sidebarOpen ? "0" : "-100%"});
            z-index: 20;
          }

          .breadcrumb-hidden {
            display: none;
          }
        }
      `}</style>
    </div>
  );
}

function SearchIcon() {
  return (
    <svg aria-hidden="true" viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="2">
      <circle cx="11" cy="11" r="7" />
      <path d="m20 20-3.5-3.5" />
    </svg>
  );
}

function GalleryIcon() {
  return (
    <svg aria-hidden="true" viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="2">
      <rect x="4" y="4" width="16" height="16" rx="2" />
      <path d="M8 4v16" />
      <path d="M4 8h4" />
      <path d="M20 8h-8" />
      <path d="M20 12h-4" />
    </svg>
  );
}

function ChevronsUpDownIcon() {
  return (
    <svg aria-hidden="true" viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="2">
      <path d="m7 9 5-5 5 5" />
      <path d="m7 15 5 5 5-5" />
    </svg>
  );
}

function CheckIcon() {
  return (
    <svg aria-hidden="true" viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="2">
      <path d="m20 6-11 11-5-5" />
    </svg>
  );
}

function ChevronRightIcon({ open }: { open: boolean }) {
  return (
    <svg
      aria-hidden="true"
      viewBox="0 0 24 24"
      width="16"
      height="16"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      style={{ transform: open ? "rotate(90deg)" : "rotate(0deg)", transition: "transform 0.15s ease" }}
    >
      <path d="m9 18 6-6-6-6" />
    </svg>
  );
}

function MenuIcon() {
  return (
    <svg aria-hidden="true" viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="2">
      <path d="M4 6h16" />
      <path d="M4 12h16" />
      <path d="M4 18h16" />
    </svg>
  );
}

export default Page;
